<?php
declare(strict_types=1);
namespace Tests\Integration;
use PDO;
use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/includes/staff_workspaces.php';
require_once dirname(__DIR__,2).'/includes/accounting_documents.php';
final class AccountingDocumentsTest extends TestCase {
 private PDO $pdo;private array $session;private string|false $root;private string $private;
 protected function setUp():void {
  $this->session=$_SESSION??[];$_SESSION=['trener_id'=>7,'staff_positions'=>['finance_manager'],'staff_active_position'=>'finance_manager'];$this->root=getenv('APP_PRIVATE_STORAGE_ROOT');$this->private=sys_get_temp_dir().'/accounting-document-'.bin2hex(random_bytes(8));mkdir($this->private);putenv('APP_PRIVATE_STORAGE_ROOT='.$this->private);
  $p=$this->pdo=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$m=require dirname(__DIR__,2).'/migrations/20261022221000_accounting_documents.php';$m['up']($p);
  $p->exec('CREATE TABLE treneri(id INT PRIMARY KEY,aktivni INT);CREATE TABLE staff_user_positions(trainer_id INT,position_code TEXT);CREATE TABLE staff_superadmins(trainer_id INT);INSERT INTO treneri VALUES(7,1);INSERT INTO staff_user_positions VALUES(7,"finance_manager");CREATE TABLE payments(payable_type VARCHAR(30),payable_id INT,variable_symbol VARCHAR(20),iban_snapshot VARCHAR(40),due_at VARCHAR(30));INSERT INTO payments VALUES("member_charge",1,"0000123456","CZ-SYNTHETIC","2026-11-01 00:00:00");CREATE TABLE sportovci(id INT PRIMARY KEY,jmeno TEXT,prijmeni TEXT);INSERT INTO sportovci VALUES(1,"Žofie","Šťastná");CREATE TABLE club_member_charges(id INT PRIMARY KEY,sportovec_id INT,public_code TEXT,status TEXT,amount_minor INT,currency TEXT,title_snapshot TEXT,period_from TEXT,period_to TEXT);INSERT INTO club_member_charges VALUES(1,1,"LOCALHOST-NEPLATIT","open",20000,"CZK","Příspěvek žákyně", "2026-01-01","2026-12-31"),(2,1,"LOCALHOST-SECOND","open",5000,"CZK","Druhý předpis",NULL,NULL);');
  \accountingDocumentConfigureIssuer($p,['name'=>'LOCALHOST Cyklistický oddíl Žluťoučký','address'=>'Příčná 12, Praha','registration_id'=>'LOCALHOST','confirmed'=>'1','approval_evidence'=>'Syntetická metodika schválená pro test.']);
  \accountingDocumentConfigureRule($p,['source_type'=>'member_charge','document_kind'=>'contribution_confirmation','category_code'=>'CLEN','activity'=>'ODDIL','title'=>'Syntetický členský příspěvek','valid_from'=>'2026-01-01','confirmed'=>'1','approval_evidence'=>'Syntetický podklad účetní.']);
  foreach(['contribution_confirmation'=>'CLEN','correction'=>'OPR'] as $kind=>$prefix)\accountingDocumentConfigureSeries($p,['kind'=>$kind,'series_year'=>(int)date('Y'),'prefix'=>$prefix,'next_number'=>1,'confirmed'=>'1','reason'=>'Syntetický počáteční stav.']);
 }
 protected function tearDown():void {$_SESSION=$this->session;$this->root===false?putenv('APP_PRIVATE_STORAGE_ROOT'):putenv('APP_PRIVATE_STORAGE_ROOT='.$this->root);if(is_dir($this->private)){foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($this->private,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST) as $f){$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());}rmdir($this->private);}}
 private function input():array{return ['source_type'=>'member_charge','source_id'=>1,'kind'=>'contribution_confirmation','effective_on'=>date('Y-m-d'),'buyer'=>['name'=>'Rodič Čestmír','address'=>'Žižkova 2, Praha'],'payer'=>['name'=>'Prarodič Řehoř'],'issuer_id'=>1,'request_key'=>'synthetic-one','line_rules'=>['charge:1'=>1],'reason'=>'Syntetický koncept pro ověření.'];}
 private function issue():array{$id=\accountingDocumentCreateDraft($this->pdo,$this->input());return \accountingDocumentIssue($this->pdo,$id,'Syntetické vydání dokumentu.');}
 public function testDraftPreviewDoesNotConsumeNumberOrCreateMoneyAndRetryReturnsSameId():void {
  $id=\accountingDocumentCreateDraft($this->pdo,$this->input());$r=\accountingDocumentGet($this->pdo,$id);self::assertSame('draft',$r['status']);self::assertNull($r['number']);self::assertSame(1,(int)$this->pdo->query('SELECT next_number FROM accounting_document_series WHERE id=1')->fetchColumn());self::assertSame($id,\accountingDocumentCreateDraft($this->pdo,array_replace($this->input(),['request_key'=>'different'])));self::assertStringContainsString('NÁHLED',\accountingDocumentHtml($r));self::assertSame(2,(int)$this->pdo->query('SELECT COUNT(*) FROM club_member_charges')->fetchColumn());
 }
 public function testIssuedPdfIsImmutableUnicodeAndDownloadHashesMatch():void {
  $r=$this->issue();$path=\accountingDocumentDownload($this->pdo,(int)$r['id']);$bytes=file_get_contents($path);self::assertStringStartsWith('%PDF-',$bytes);self::assertGreaterThan(10000,strlen($bytes));self::assertSame(hash('sha256',$bytes),$r['pdf_sha256']);self::assertSame('issued',$r['status']);self::assertStringContainsString('Žofie',\accountingDocumentHtml($r));self::assertStringContainsString('Nejsme plátci DPH',\accountingDocumentHtml($r));
  $this->pdo->exec('UPDATE sportovci SET jmeno="Změněná"');$again=\accountingDocumentIssue($this->pdo,(int)$r['id'],'Opakování stejného vydání.');self::assertSame($r['snapshot_json'],$again['snapshot_json']);self::assertSame($bytes,file_get_contents(\accountingDocumentDownload($this->pdo,(int)$r['id'])));self::assertSame(2,(int)$this->pdo->query('SELECT next_number FROM accounting_document_series WHERE id=1')->fetchColumn());
 }
 public function testStorageFailureKeepsNumberAndRetryIssuesSameDocument():void {
  $id=\accountingDocumentCreateDraft($this->pdo,$this->input());putenv('APP_PRIVATE_STORAGE_ROOT='.dirname(__DIR__,2));try{\accountingDocumentIssue($this->pdo,$id,'Syntetická chyba úložiště.');self::fail();}catch(\RuntimeException){self::assertSame('failed',\accountingDocumentGet($this->pdo,$id)['status']);}
  $number=\accountingDocumentGet($this->pdo,$id)['number'];self::assertNotNull($number);putenv('APP_PRIVATE_STORAGE_ROOT='.$this->private);$r=\accountingDocumentIssue($this->pdo,$id,'Opakování po opravě úložiště.');self::assertSame($number,$r['number']);self::assertSame('issued',$r['status']);self::assertSame(2,(int)$this->pdo->query('SELECT next_number FROM accounting_document_series WHERE id=1')->fetchColumn());
 }
 public function testPartialCorrectionReservesRemainingAmountWithoutChangingOriginalOrMoney():void {
  $r=$this->issue();$id=\accountingDocumentCreateCorrection($this->pdo,(int)$r['id'],[['line_key'=>'charge:1','quantity'=>0,'amount_minor'=>5000]],'correction-one','Syntetická částečná sleva.');self::assertSame(-5000,(int)\accountingDocumentGet($this->pdo,$id)['total_minor']);self::assertSame($id,\accountingDocumentCreateCorrection($this->pdo,(int)$r['id'],[['line_key'=>'charge:1','quantity'=>0,'amount_minor'=>5000]],'correction-one','Opakovaný požadavek.'));$corrected=\accountingDocumentIssue($this->pdo,$id,'Vydání opravného dokladu.');self::assertSame('issued',$corrected['status']);self::assertSame($r['snapshot_json'],\accountingDocumentGet($this->pdo,(int)$r['id'])['snapshot_json']);self::assertSame(20000,(int)$this->pdo->query('SELECT amount_minor FROM club_member_charges WHERE id=1')->fetchColumn());
  $this->expectException(\DomainException::class);\accountingDocumentCreateCorrection($this->pdo,(int)$r['id'],[['line_key'=>'charge:1','quantity'=>1,'amount_minor'=>15001]],'correction-over','Pokus o překročení ceny.');
 }
 public function testCorrectionQuantityAndRepeatedLineCannotExceedOriginal():void {
  $r=$this->issue();foreach([[['line_key'=>'charge:1','quantity'=>2,'amount_minor'=>1]],[['line_key'=>'charge:1','quantity'=>0,'amount_minor'=>1],['line_key'=>'charge:1','quantity'=>0,'amount_minor'=>1]]] as $lines){try{\accountingDocumentCreateCorrection($this->pdo,(int)$r['id'],$lines,'bad-correction','Syntetický chybný požadavek.');self::fail();}catch(\DomainException){self::assertSame(1,(int)$this->pdo->query('SELECT COUNT(*) FROM accounting_documents')->fetchColumn());}}
 }
 public function testMissingClassificationOrIssuerFailsClosed():void {
  foreach([['line_rules'=>[]],['issuer_id'=>999]] as $bad){try{\accountingDocumentCreateDraft($this->pdo,array_replace($this->input(),$bad));self::fail();}catch(\DomainException){self::assertSame(0,(int)$this->pdo->query('SELECT COUNT(*) FROM accounting_documents')->fetchColumn());}}
 }
 public function testRevokedRoleCannotIssueFromStaleSession():void {
  $id=\accountingDocumentCreateDraft($this->pdo,$this->input());$this->pdo->exec('DELETE FROM staff_user_positions');$this->expectException(\DomainException::class);\accountingDocumentIssue($this->pdo,$id,'Po odvolání přístupu.');
 }
 public function testChangedSourceBlocksNumberReservation():void {
  $id=\accountingDocumentCreateDraft($this->pdo,$this->input());$this->pdo->exec('UPDATE club_member_charges SET amount_minor=25000 WHERE id=1');try{\accountingDocumentIssue($this->pdo,$id,'Změněný zdroj před vydáním.');self::fail();}catch(\DomainException){self::assertNull(\accountingDocumentGet($this->pdo,$id)['number']);}
 }
 public function testPartiesCanChangeOnlyBeforeNumberReservation():void {
  $id=\accountingDocumentCreateDraft($this->pdo,$this->input());\accountingDocumentReviseParties($this->pdo,$id,['name'=>'Organizace','address'=>'Sídlo organizace'],[],'Oprava odběratele před vydáním.');$r=\accountingDocumentIssue($this->pdo,$id,'Vydání po kontrole.');self::assertStringContainsString('Organizace',$r['snapshot_json']);$this->expectException(\DomainException::class);\accountingDocumentReviseParties($this->pdo,$id,['name'=>'Cizí','address'=>'Adresa'],[],'Zakázaná změna vydaného dokladu.');
 }
 public function testTamperedPrivatePdfCannotBeDownloaded():void {$r=$this->issue();$path=\accountingDocumentDownload($this->pdo,(int)$r['id']);file_put_contents($path,'tampered');$this->expectException(\DomainException::class);\accountingDocumentDownload($this->pdo,(int)$r['id']);}
 public function testUserHtmlEscapedAndNoExternalResourcesAllowed():void {$id=\accountingDocumentCreateDraft($this->pdo,array_replace_recursive($this->input(),['buyer'=>['name'=>'<img src="https://example.invalid/secret">']]));$html=\accountingDocumentHtml(\accountingDocumentGet($this->pdo,$id));self::assertStringContainsString('&lt;img',$html);self::assertStringNotContainsString('<img',$html);}
 public function testCashReceiptLinksExistingMoneyWithoutDuplicatingIt():void {
  $this->pdo->exec('CREATE TABLE accounting_accounts(id INT,kind TEXT,name TEXT);INSERT INTO accounting_accounts VALUES(1,"cash","LOCALHOST pokladna");CREATE TABLE accounting_movements(id INT,account_id INT,amount_minor INT,effective_on TEXT,currency TEXT,source_reference TEXT,evidence TEXT);');$this->pdo->prepare('INSERT INTO accounting_movements VALUES(1,1,5000,?,"CZK","LOCALHOST-CASH","Převzetí doložené hotovosti")')->execute([date('Y-m-d')]);
  $rule=\accountingDocumentConfigureRule($this->pdo,['source_type'=>'movement','document_kind'=>'cash_receipt','category_code'=>'CLEN','activity'=>'ODDIL','title'=>'Hotovost','valid_from'=>'2026-01-01','confirmed'=>'1','approval_evidence'=>'Syntetická metodika.']);\accountingDocumentConfigureSeries($this->pdo,['kind'=>'cash_receipt','series_year'=>(int)date('Y'),'prefix'=>'PPD','next_number'=>1,'confirmed'=>'1','reason'=>'Syntetická řada.']);
  $id=\accountingDocumentCreateDraft($this->pdo,array_replace($this->input(),['source_type'=>'movement','kind'=>'cash_receipt','line_rules'=>['movement:1'=>$rule]]));$r=\accountingDocumentIssue($this->pdo,$id,'Vydání PPD k existujícím penězům.');self::assertSame('issued',$r['status']);self::assertSame(1,(int)$this->pdo->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());self::assertStringContainsString('Příjmový pokladní doklad',\accountingDocumentHtml($r));
 }
 public function testChangedSourceCanRebuildUnnumberedDraftWithNewReview():void {
  $id=\accountingDocumentCreateDraft($this->pdo,$this->input());$this->pdo->exec('UPDATE club_member_charges SET amount_minor=25000 WHERE id=1');
  $rebuilt=\accountingDocumentCreateDraft($this->pdo,array_replace($this->input(),['request_key'=>'reviewed-again']));self::assertSame($id,$rebuilt);self::assertSame(25000,(int)\accountingDocumentGet($this->pdo,$id)['total_minor']);self::assertSame(1,(int)$this->pdo->query("SELECT COUNT(*) FROM accounting_document_events WHERE action='draft_rebuilt'")->fetchColumn());self::assertSame('issued',\accountingDocumentIssue($this->pdo,$id,'Ověřená aktualizace případu.')['status']);
 }
 public function testVoidDraftReleasesCaseButCannotIssueOrDeleteHistory():void {
  $id=\accountingDocumentCreateDraft($this->pdo,$this->input());\accountingDocumentVoidDraft($this->pdo,$id,'Chybný nečíslovaný koncept.');self::assertSame('void',\accountingDocumentGet($this->pdo,$id)['status']);
  $replacement=\accountingDocumentCreateDraft($this->pdo,array_replace($this->input(),['request_key'=>'replacement']));self::assertNotSame($id,$replacement);self::assertSame(2,(int)$this->pdo->query('SELECT COUNT(*) FROM accounting_documents')->fetchColumn());$this->expectException(\DomainException::class);\accountingDocumentIssue($this->pdo,$id,'Zakázané oživení konceptu.');
 }
 public function testVoidCorrectionReleasesReservationAndNumberedDocumentCannotVoid():void {
  $r=$this->issue();$id=\accountingDocumentCreateCorrection($this->pdo,(int)$r['id'],[['line_key'=>'charge:1','quantity'=>1,'amount_minor'=>20000]],'wrong-correction','Chybná úplná oprava.');\accountingDocumentVoidDraft($this->pdo,$id,'Oprava se nemá vydat.');$next=\accountingDocumentCreateCorrection($this->pdo,(int)$r['id'],[['line_key'=>'charge:1','quantity'=>1,'amount_minor'=>20000]],'new-correction','Nové správné rozhodnutí.');self::assertGreaterThan($id,$next);$this->expectException(\DomainException::class);\accountingDocumentVoidDraft($this->pdo,(int)$r['id'],'Pokus o zrušení vydaného.');
 }
 public function testOriginalPaymentReferenceAndIssuedDateAreFrozen():void {
  $r=$this->issue();$snapshot=json_decode($r['snapshot_json'],true,512,JSON_THROW_ON_ERROR);self::assertSame('0000123456',$snapshot['variable_symbol']);self::assertSame(date('Y-m-d'),$snapshot['issued_on']);self::assertStringContainsString('0000123456',\accountingDocumentHtml($r));self::assertStringContainsString('CZ-SYNTHETIC',\accountingDocumentHtml($r));$this->pdo->exec('UPDATE payments SET variable_symbol="999"');self::assertSame($r['snapshot_json'],\accountingDocumentGet($this->pdo,(int)$r['id'])['snapshot_json']);
 }
 public function testMixedOrderIncludesGoodsCourseEventVelodromeShippingAndDiscountExactlyOnce():void {
  $this->pdo->exec('CREATE TABLE shop_orders(id INT,public_code TEXT,status TEXT,total_minor INT,currency TEXT,customer_name_snapshot TEXT,shipping_amount_minor INT,discount_minor INT,account_id INT);INSERT INTO shop_orders VALUES(1,"LOCALHOST-ORDER","new",30000,"CZK","Organizace LOCALHOST",1000,2000,9);CREATE TABLE shop_order_items(id INT,order_id INT,beneficiary_sportovec_id INT,product_name_snapshot TEXT,quantity INT,line_amount_minor INT,club_program_offer_id INT,product_id INT,variant_id INT);INSERT INTO shop_order_items VALUES(1,1,1,"Kurz a oblečení",2,20000,4,5,6);CREATE TABLE club_program_offers(id INT,product_id INT,variant_id INT,starts_on TEXT,ends_on TEXT);INSERT INTO club_program_offers VALUES(4,5,6,"2027-01-01","2027-06-30");CREATE TABLE club_event_order_items(id INT,order_id INT,beneficiary_sportovec_id INT,event_name_snapshot TEXT,quantity INT,line_amount_minor INT);INSERT INTO club_event_order_items VALUES(2,1,1,"Soustředění",1,5000);CREATE TABLE public_velodrome_order_items(id INT,order_id INT,beneficiary_sportovec_id INT,lesson_name_snapshot TEXT,quantity INT,line_amount_minor INT,lesson_date_snapshot TEXT);INSERT INTO public_velodrome_order_items VALUES(3,1,1,"Velodrom",1,6000,"2027-01-02");INSERT INTO payments VALUES("shop_order",1,"0000000013","CZ-TEST","2026-11-01 23:59:59");');
  $rule=\accountingDocumentConfigureRule($this->pdo,['source_type'=>'order','document_kind'=>'invoice','category_code'=>'TEST','activity'=>'TEST','title'=>'Test explicitního členění','valid_from'=>'2026-01-01','confirmed'=>'1','approval_evidence'=>'Syntetická metodika.']);\accountingDocumentConfigureSeries($this->pdo,['kind'=>'invoice','series_year'=>(int)date('Y'),'prefix'=>'FA','next_number'=>1,'confirmed'=>'1','reason'=>'Syntetická řada.']);
  $input=array_replace($this->input(),['source_type'=>'order','kind'=>'invoice','due_on'=>'2026-11-01','line_rules'=>array_fill_keys(['item:1','event:2','velodrome:3','shipping','discount'],$rule)]);$id=\accountingDocumentCreateDraft($this->pdo,$input);$r=\accountingDocumentIssue($this->pdo,$id,'Ověřené smíšené položky.');$s=json_decode($r['snapshot_json'],true,512,JSON_THROW_ON_ERROR);self::assertCount(5,$s['lines']);self::assertSame(30000,array_sum(array_column($s['lines'],'amount_minor')));self::assertSame('0000000013',$s['variable_symbol']);self::assertSame(['2027-01-01','2027-06-30'],$s['lines'][0]['service_period']);self::assertSame('2026-11-01',$s['due_on']);self::assertStringContainsString('2027-01-01',\accountingDocumentHtml($r));
 }
}
